	.pb-safe.svelte-nbiy9y {
		padding-bottom: env(safe-area-inset-bottom, 0);
	}

	/* Menu starts collapsed, expands upward using transform instead of max-height */
	.bottom-nav-menu.svelte-nbiy9y {
		transform: translateY(100%);
		transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
		will-change: transform;
	}
	.menu-expand.svelte-nbiy9y {
		transform: translateY(0);
	}
	.menu-collapse.svelte-nbiy9y {
		transform: translateY(100%);
	}

	/* Simplified scrollbar styling - removed problematic scrollbar-color */
	.bottom-nav-menu.svelte-nbiy9y::-webkit-scrollbar {
		width: 4px;
	}

	.bottom-nav-menu.svelte-nbiy9y::-webkit-scrollbar-track {
		background: transparent;
	}

	.bottom-nav-menu.svelte-nbiy9y::-webkit-scrollbar-thumb {
		background: hsl(var(--p));
		border-radius: 2px;
	}

	.bottom-nav-menu.svelte-nbiy9y::-webkit-scrollbar-thumb:hover {
		background: hsl(var(--p) / 0.8);
	}

	/* Optimized arrow animations for better performance */
	.dropdown-arrow.svelte-nbiy9y {
		transform-origin: center;
		transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
		will-change: transform;
		transform: rotate(0deg);
	}

	.dropdown-arrow.dropdown-open.svelte-nbiy9y {
		transform: rotate(180deg);
	}

	/* Simplified hover effects to avoid complex transform combinations */
	.menu.svelte-nbiy9y li:where(.svelte-nbiy9y) > button:where(.svelte-nbiy9y):hover .dropdown-arrow:where(.svelte-nbiy9y) {
		transform: rotate(0deg) scale(1.05);
	}

	.menu.svelte-nbiy9y li:where(.svelte-nbiy9y) > button:where(.svelte-nbiy9y):hover .dropdown-arrow.dropdown-open:where(.svelte-nbiy9y) {
		transform: rotate(180deg) scale(1.05);
	}

	/* Ensure smooth transitions for all interactive elements */
	.dock.svelte-nbiy9y a:where(.svelte-nbiy9y),
	.dock.svelte-nbiy9y button:where(.svelte-nbiy9y) {
		will-change: transform, opacity;
	}

	/* Optimize hamburger menu animations */
	.dock.svelte-nbiy9y button[data-menu-button]:where(.svelte-nbiy9y) span:where(.svelte-nbiy9y) {
		will-change: transform, opacity;
		transform-origin: center;
		backface-visibility: hidden;
	}

	/* Ensure all transitions use GPU acceleration */
	.dock.svelte-nbiy9y a:where(.svelte-nbiy9y),
	.dock.svelte-nbiy9y button:where(.svelte-nbiy9y),
	.bottom-nav-menu.svelte-nbiy9y,
	.dropdown-arrow.svelte-nbiy9y {
		backface-visibility: hidden;
		transform: translateZ(0);
	}

	/* Ensure any ::after pseudo-elements use composited animations */
	.dropdown-arrow.svelte-nbiy9y::after {
		will-change: transform;
		backface-visibility: hidden;
		transform: translateZ(0);
	}

	/* Override any scrollbar-color properties that might cause issues */
