	/* Ensure all animations use GPU acceleration */
	.svelte-nbiy9y {
		transform-style: preserve-3d;
	}

	/* Optimize all transitions for better performance */
	.transition-all.svelte-nbiy9y {
		will-change: transform, opacity;
